package com.smartfreight.inbox.entity;

import jakarta.persistence.*;
import lombok.*;

/**
 * JPA entity mapped to the {@code app_user} table in the database.
 *
 * Used for Spring Security authentication via {@link com.smartfreight.inbox.config.DbUserDetailsService}.
 * Users are created through Flyway migrations (V2, V3) — not programmatically.
 */
@Entity
@Table(name = "app_user")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class User {

    /** Primary key — automatically generated by PostgreSQL. */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Unique email address — used as the login name.
     * Spring Security looks up the user by this field.
     */
    @Column(name = "email", nullable = false, unique = true)
    private String email;

    /**
     * BCrypt-encoded password — plain-text passwords are never stored.
     * BCrypt automatically generates a unique salt for each password.
     */
    @Column(name = "password", nullable = false)
    private String password;

    /**
     * User role: ADMIN, OPERATOR, VIEWER, etc.
     * Used for authorisation — who can view and edit what.
     * If null, DbUserDetailsService assigns the default role OPERATOR.
     */
    @Column(name = "role")
    private String role;
}
